import{c as n,Q as t,j as r,g as l}from"./chunks/framework.hhGiamYR.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{"date":"2026-08-01T00:00:00.000Z","source":"discourses/book2/01-第一章.md"},"headers":[],"relativePath":"fragments/2026-08-01.md","filePath":"fragments/2026-08-01.md"}'),a={name:"fragments/2026-08-01.md"};function s(o,e,u,p,c,d){return t(),r("div",null,[...e[0]||(e[0]=[l("p",null,'普鲁塔克说罗马人受惠于运气多于德行。李维也差不多。他们错了——但不是全错。他们只是把一个需要拆解的东西叫作一个名字。罗马人从未同时打两场大战——他们说这是运气。但不是。这是策略。是制度。是一个共和国按自己的节奏吃人，而不是被人吃。我在读这一章的时候忽然想到：他们把这叫作"运气"，是因为他们不敢说"别人太蠢"。迦太基人看着罗马人吞掉萨谟奈人，不动。看着吞掉托斯卡纳人，不动。直到大火烧到自己城下，才发现兵力不够了。这不是罗马的运气。这是迦太基的愚蠢。但普卢塔克不会这么写。他得对迦太基人客气一点。',-1),l("hr",null,null,-1),l("p",null,'迦太基人隔岸观火的时候在想什么——我在想这个问题。他们控制了整个阿非利加，占了撒丁和西西里，统治着西班牙的一部分。他们是强权。而罗马人还在跟萨谟奈人纠缠。他们为什么不动手？不是因为距离太远。不是因为兵力不足。是因为——他们在等。等罗马人被别人打败。等战局烂到不需要自己出手。他们跟罗马人暗通款曲，以为这是精明。这不就是佛罗伦萨吗？我亲眼看着切萨雷·博尔贾一个接一个吃掉那些小领主——然后轮到我们。所有人都在等别人先动手，等别人先流血，等到轮到自己了，已经没有军队了。我在信里写"不要指望别人出手"，但没有人听。迦太基人没听过我的信。佛罗伦萨人听过，但他们也没听。',-1),l("hr",null,null,-1),l("p",null,'每次罗马人进入一个新地区，都有当地人给他们开门。卡普阿人帮他们进入萨谟奈，马麦丁人帮他们进入西西里，马昔尼萨帮他们进入阿非利加。罗马人从不缺少"使自己的事业更加容易的支持者"。我读到这句话的时候停了下来。"增加事业容易性的支持者"——这是我外交生涯里每天找的东西。在法国，找反对国王的人。在罗马涅，找不满博尔贾的城市。在每一个外交场合，找那个愿意给我们开门的人。但罗马人能找到，我们找不到。不是因为意大利没有那样的人——是因为我们没有罗马人那样的东西可以许诺。你手里什么都没有，谁会给你开门？合作者只追随强者。合作者不是原因，是结果。',-1),l("hr",null,null,-1),l("p",null,"……有时候我觉得我在说服的不是普卢塔克。是我自己。《君主论》第十五章我说机运只主宰我们一半的行动。这一章我又说罗马的帝国是德行的成果不是运气。但我知道自己为什么这么坚持。不是因为证据比普卢塔克更强——是因为我需要德行比运气重要。我需要相信一个人在正确的事情上坚持足够久，就能改变些什么。如果我不相信这个，那我这十四年的国务厅、六次吊刑、这本没人读的书——就全都是运气的玩笑。一个被命运反复碾压的人，写了整整一本书证明命运只占一半。……也许普卢塔克是对的。也许他占两半。但我不会这样写。不是因为我不诚实。是因为如果我写了，我就站不起来了。",-1),l("hr",null,null,-1),l("p",null,"迦太基人犯的那个错误，我在法国犯过。我在博尔贾面前犯过。我在美第奇面前也犯过。错误是一样的：以为时间站在自己这边。以为可以等。以为在这场博弈里我是那个看的人，别人是桌上的棋子。实际上我才是被人看的那一颗。马其顿的菲利普在等。安条克在等。法兰克人在等。等到罗马人腾出手来，他们都死了。……人的傲慢不在于主动攻击——那种傲慢反而有救。真正致命的傲慢是：你坐在那里，觉得自己不是猎物。然后你闻到烟味了。",-1)])])}const i=n(a,[["render",s]]);export{f as __pageData,i as default};
